CREATE TABLE break.audit_event (
  audit_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  event_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  actor_type text NOT NULL CHECK (actor_type IN ('human','job','system')),
  actor_id text NOT NULL CHECK (char_length(actor_id) BETWEEN 1 AND 254),
  ticket_id text NOT NULL CHECK (char_length(ticket_id) BETWEEN 1 AND 64),
  break_id text NOT NULL,
  leg_id text NULL,
  action text NOT NULL,
  before_image jsonb NULL,
  after_image jsonb NOT NULL,
  src_ip inet NULL,
  app_version text NOT NULL,
  row_hash bytea NOT NULL,
  CONSTRAINT audit_event_create_before_null CHECK (action <> 'create' OR before_image IS NULL),
  CONSTRAINT audit_event_noncreate_before CHECK (action = 'create' OR before_image IS NOT NULL)
);

CREATE INDEX audit_event_break_id_event_at ON break.audit_event (break_id, event_at);
CREATE INDEX audit_event_event_at ON break.audit_event (event_at);
CREATE INDEX audit_event_ticket_id ON break.audit_event (ticket_id);
CREATE INDEX audit_event_actor_id ON break.audit_event (actor_id);

REVOKE UPDATE, DELETE, TRUNCATE ON break.audit_event FROM PUBLIC;
REVOKE UPDATE, DELETE, TRUNCATE ON break.audit_event FROM break_app, break_readonly, helen_audit;
GRANT INSERT, SELECT ON break.audit_event TO break_app;
GRANT SELECT ON break.audit_event TO break_readonly, helen_audit;

-- block table owner mistakes from app connections (owner is rds_superuser / migrate role, not break_app)
ALTER TABLE break.audit_event ENABLE ROW LEVEL SECURITY;
CREATE POLICY audit_event_insert_only ON break.audit_event
  FOR INSERT TO break_app WITH CHECK (true);
CREATE POLICY audit_event_select ON break.audit_event
  FOR SELECT TO break_app, break_readonly, helen_audit USING (true);
-- no UPDATE/DELETE policies, so those commands fail even if GRANT is wrong later
